'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled CoachMark, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './coach-mark.css'

/**
 * CoachMark: the bubble that points at one control and says what it is for.
 *
 * It is guidance beside the game, not a dialog in front of it. That distinction
 * is the whole component: REQ-037 says a coach mark must be dismissible by
 * keyboard and must NOT trap focus, which is the opposite of the modal rule
 * everyone reaches for. So nothing here calls `focus()`, nothing sets `inert`
 * or `aria-modal`, the root takes no tabindex, and the only thing it adds to
 * the tab order is its own dismiss button, in document order, which Tab leaves
 * on the next press. A player who never looks at it can tab straight past.
 *
 * Dismissal is a state, not an unmount. `data-gs-dismissed="true"` stays in the
 * DOM so a test can tell "the player closed it" from "it was never rendered",
 * and so the keyboard dismissal the spec requires lands somewhere assertable.
 *
 * It performs nothing. It does not decide when to appear, remember that it was
 * closed, or advance a sequence. The host owns `dismissed` and the host owns
 * what `onDismiss` means.
 */

export type CoachMarkPlacement =
  | 'top'
  | 'bottom'
  | 'left'
  | 'right'
  | 'center'
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right'

export interface CoachMarkProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The id of the control this guidance is about. A coach mark needs one. */
  anchor: string
  /** Where it sits within its container. A coach mark needs this too. */
  placement?: CoachMarkPlacement
  /** The short heading, if it has one. The body is `children`. */
  title?: string
  /** Position in a sequence, from 1. Rendered as "Step 2 of 5" above the body. */
  step?: number
  /** The total. The same attribute progress uses: "2 of 5" is one idea. */
  max?: number
  /** The one the sequence is on now. Not `selected`: the player did not pick it. */
  active?: boolean
  /** The player closed it and it stays closed. A state, never an unmount. */
  dismissed?: boolean
  /** Called on the close button and on Escape. Absent means undismissable. */
  onDismiss?: () => void
  /** The close control's accessible name. */
  dismissLabel?: string
}

/** Glyph, because a control that is only an outline is not a control. */
const CLOSE = '×'

/** From the contract's table of state words, so five components share one. */
const STATE_WORD = { active: 'current' } as const

export function CoachMark({
  anchor,
  placement = 'top',
  title,
  step,
  max,
  active = false,
  dismissed = false,
  onDismiss,
  dismissLabel = 'Dismiss',
  className,
  children,
  ...rest
}: CoachMarkProps) {
  // Escape listens on the document, not on the root, because focus is never
  // held here: the player may be anywhere on the page when they decide they
  // have read enough, and a handler on the root would only fire for the one
  // player whose focus happens to be inside it. That is the cost of not
  // trapping focus, and this is what pays it.
  //
  // Bound only while there is something to dismiss, so a closed coach mark
  // leaves no listener behind and Escape reaches the host again.
  const live = !dismissed && onDismiss !== undefined
  React.useEffect(() => {
    if (!live) return
    function onKeyDown(event: KeyboardEvent) {
      // Not `stopPropagation` and not `preventDefault`: a coach mark is not
      // modal, so it has no claim on the key. The host's own Escape handling,
      // and the browser's, both still run.
      if (event.key === 'Escape') onDismiss?.()
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [live, onDismiss])

  const counter = step !== undefined && max !== undefined ? `Step ${step} of ${max}` : undefined

  return (
    <div
      {...rest}
      className={['gs-coach-mark', className].filter(Boolean).join(' ')}
      data-gs-component="coach-mark"
      data-gs-anchor={anchor}
      data-gs-placement={placement}
      data-gs-step={step}
      data-gs-max={max}
      data-gs-active={active ? 'true' : undefined}
      data-gs-dismissed={dismissed ? 'true' : undefined}
      // A dismissed coach mark is no longer announced, which is the contract's
      // own word for it: none. `hidden` takes it out of the accessible tree and
      // out of the tab order in one move, and the attribute above keeps it
      // findable by a test.
      hidden={dismissed || undefined}
      // Guidance, not a dialog, and never an alert. `polite` so that a step
      // advancing inside a coach mark that is already on screen is read out
      // without interrupting the player or moving the caret.
      role="note"
      aria-live="polite"
    >
      {/* Nothing focusable renders while dismissed. `hidden` already removes it
          from the tab order, but a control that exists only to be unreachable
          is a control waiting for the first stylesheet that overrides
          `display`. */}
      {dismissed ? null : (
        <>
          <span
            className="gs-coach-mark__arrow"
            data-gs-scope="coach-mark" data-gs-part="arrow"
            data-gs-motion="pulse"
            data-gs-animates="motion"
            aria-hidden="true"
          />
          {title ? (
            <span className="gs-coach-mark__title" data-gs-scope="coach-mark" data-gs-part="label">
              {title}
            </span>
          ) : null}
          {counter ? (
            <span className="gs-coach-mark__step" data-gs-scope="coach-mark" data-gs-part="step">
              {counter}
            </span>
          ) : null}
          <span className="gs-coach-mark__body" data-gs-scope="coach-mark" data-gs-part="body">
            {children}
          </span>
          {/* Read by a screen reader, never seen. The contract pairs every
              state with a change to the accessible name, and "current" is the
              word it fixes for `data-gs-active`. */}
          {active ? (
            <span className="gs-coach-mark__announcement" data-gs-scope="coach-mark" data-gs-part="announcement">
              {STATE_WORD.active}
            </span>
          ) : null}
          {onDismiss ? (
            <button
              type="button"
              className="gs-coach-mark__dismiss gs-action-type gs-pressable"
              data-gs-scope="coach-mark" data-gs-part="dismiss"
              aria-label={dismissLabel}
              onClick={onDismiss}
            >
              <span aria-hidden="true">{CLOSE}</span>
            </button>
          ) : null}
        </>
      )}
    </div>
  )
}

/* Coach mark. Every value comes from a token; nothing here is a literal colour.

   Specimen 3g draws this bubble and design/twins/3g.json measures ours against
   it: a reward-coloured plate, outlined in edge, 16px round, padded 12 by 14,
   with a hard shelf beneath and a two-layer beak pointing at the target. It
   used to be a raised blue card with a high edge, which is a card and not a
   coach mark: a coach mark is the one thing on screen in the reward colour, so
   the eye goes to it before anything else. */

/* Placement is CSS, driven by `data-gs-placement`, the way choice drives its
   grid from `data-gs-presentation`. No positioning library: the contract already
   names where the thing sits, and a library would compute a second answer that
   a test could not read. It positions against the nearest positioned ancestor,
   so a host puts one around the surface the guidance belongs to. */
.gs-coach-mark {
  position: absolute;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: start;
  gap: var(--gs-space-1) var(--gs-space-2);

  max-width: 18rem;
  padding: var(--gs-space-3) var(--gs-space-inset);

  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);

  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
  /* The drawing puts a bare 5px shelf under the bubble. depth.raised is the
     nearest token and adds a highlight line along the top; a shelf on its own
     is raised as a token request. */
  box-shadow: var(--gs-depth-raised);
}

/* -- placement ------------------------------------------------------------ */
/* Above or below the target, the bubble spans the surface with a margin each
   side, as drawn; the corner placements and the sides keep their own width. */
.gs-coach-mark[data-gs-placement='top']    { top: var(--gs-space-4); left: var(--gs-space-6); right: var(--gs-space-6); }
.gs-coach-mark[data-gs-placement='bottom'] { bottom: var(--gs-space-4); left: var(--gs-space-6); right: var(--gs-space-6); }
/* Spanning is a phone's width: on a wide surface the same rule made a 2000px
   bubble with the words at one end and the close at the other. Left and right
   still pin the margins; the cap and the auto margins centre it above that. */
.gs-coach-mark[data-gs-placement='top'],
.gs-coach-mark[data-gs-placement='bottom'] {
  max-width: 24rem;
  margin-inline: auto;
}
.gs-coach-mark[data-gs-placement='left']   { left: var(--gs-space-4); top: 50%; transform: translateY(-50%); }
.gs-coach-mark[data-gs-placement='right']  { right: var(--gs-space-4); top: 50%; transform: translateY(-50%); }
.gs-coach-mark[data-gs-placement='center'] { top: 50%; left: 50%; transform: translate(-50%, -50%); }
.gs-coach-mark[data-gs-placement='top-left']     { top: var(--gs-space-4); left: var(--gs-space-4); }
.gs-coach-mark[data-gs-placement='top-right']    { top: var(--gs-space-4); right: var(--gs-space-4); }
.gs-coach-mark[data-gs-placement='bottom-left']  { bottom: var(--gs-space-4); left: var(--gs-space-4); }
.gs-coach-mark[data-gs-placement='bottom-right'] { bottom: var(--gs-space-4); right: var(--gs-space-4); }

/* -- the beak, which is what makes it point rather than float -------------- */
/* Two triangles, the way the drawing builds it: an edge-coloured one 24 wide
   and 14 tall, and the reward-coloured one inside it, smaller by the stroke on
   every side and sitting two pixels higher, so the beak reads as outlined in
   the same 3px as the bubble. It sits on the edge facing the anchor, so the
   side it takes is the opposite of the side the mark sits on; the other three
   sides are the same shape turned. */
.gs-coach-mark__arrow {
  position: absolute;
  width: 0;
  height: 0;
  border-left: var(--gs-space-3) solid transparent;
  border-right: var(--gs-space-3) solid transparent;
  border-top: var(--gs-space-inset) solid var(--gs-color-edge);
  /* The pulse is the only movement here, so it is `motion` and stops dead under
     reduced motion. Nothing a player needs to read depends on it: the mark's
     position, its beak and its text all say the same thing standing still.

     The loop itself is motion.css's: the beak carries data-gs-motion="pulse"
     and the drawing's keyframe scales it 1 to 1.06 over the pulse token, the
     way the drawing pulses a coach-mark's target (3g). This file used to
     fade the beak to half instead, which the drawing does nowhere. */
}

/* The beak is two bordered triangles, not a turned square, so the pulse is a
   bare scale: the same two stops as gs-pulse with no rotation. A rotate(45deg)
   here turned the 24 by 14 triangle into a 28px lozenge the twin caught. */
.gs-coach-mark__arrow[data-gs-motion='pulse'] {
  animation-name: gs-coach-mark-beak;
}

@keyframes gs-coach-mark-beak {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.06); }
}

.gs-coach-mark__arrow::after {
  content: '';
  position: absolute;
  top: calc(-1 * var(--gs-space-4));
  left: calc(-1 * (var(--gs-space-3) - var(--gs-stroke-ui)));
  width: 0;
  height: 0;
  border-left: calc(var(--gs-space-3) - var(--gs-stroke-ui)) solid transparent;
  border-right: calc(var(--gs-space-3) - var(--gs-stroke-ui)) solid transparent;
  border-top: calc(var(--gs-space-inset) - var(--gs-stroke-ui)) solid var(--gs-color-reward-solid);
}

.gs-coach-mark[data-gs-placement='top'] .gs-coach-mark__arrow,
.gs-coach-mark[data-gs-placement='top-left'] .gs-coach-mark__arrow,
.gs-coach-mark[data-gs-placement='top-right'] .gs-coach-mark__arrow {
  bottom: calc(-1 * var(--gs-space-4));
}

.gs-coach-mark[data-gs-placement='bottom'] .gs-coach-mark__arrow,
.gs-coach-mark[data-gs-placement='bottom-left'] .gs-coach-mark__arrow,
.gs-coach-mark[data-gs-placement='bottom-right'] .gs-coach-mark__arrow {
  top: calc(-1 * var(--gs-space-4));
  transform: rotate(180deg);
}

/* Centred above or below the target; in a corner, in from the corner. */
.gs-coach-mark[data-gs-placement='top'] .gs-coach-mark__arrow,
.gs-coach-mark[data-gs-placement='bottom'] .gs-coach-mark__arrow {
  left: 50%;
  transform: translateX(-50%);
}

.gs-coach-mark[data-gs-placement='bottom'] .gs-coach-mark__arrow {
  transform: translateX(-50%) rotate(180deg);
}

.gs-coach-mark[data-gs-placement='top-left'] .gs-coach-mark__arrow,
.gs-coach-mark[data-gs-placement='bottom-left'] .gs-coach-mark__arrow {
  left: var(--gs-space-6);
}

.gs-coach-mark[data-gs-placement='top-right'] .gs-coach-mark__arrow,
.gs-coach-mark[data-gs-placement='bottom-right'] .gs-coach-mark__arrow {
  right: var(--gs-space-6);
}

.gs-coach-mark[data-gs-placement='left'] .gs-coach-mark__arrow {
  right: calc(-1 * var(--gs-space-4));
  top: var(--gs-space-6);
  transform: rotate(-90deg);
}

.gs-coach-mark[data-gs-placement='right'] .gs-coach-mark__arrow {
  left: calc(-1 * var(--gs-space-4));
  top: var(--gs-space-6);
  transform: rotate(90deg);
}

/* Centred guidance points at nothing in particular, so it grows no beak. */
.gs-coach-mark[data-gs-placement='center'] .gs-coach-mark__arrow { display: none; }

/* -- contents -------------------------------------------------------------- */
.gs-coach-mark__title {
  grid-column: 1;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
}

/* "STEP 2 OF 4": the display face, heavy, in capitals, in the bubble's own
   ink. type.figure is the display token nearest the drawing's 11px; the label
   floor is 12. */
.gs-coach-mark__step {
  grid-column: 1;
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  text-transform: uppercase;
}

.gs-coach-mark__body { grid-column: 1; }

/* The active mark is the one the sequence is on, and the drawing draws it
   exactly as the mark above: reward plate, edge outline. It used to take the
   selected stroke, which is the colour of a choice the player made, and a
   coach mark is not one. The accessible name carries "current"; nothing on
   screen needs to, because a coach mark that is showing is the current one. */

/* -- the dismiss control --------------------------------------------------- */
/* An ordinary button in ordinary document order. Nothing here holds focus, so
   Tab reaches it once and then leaves for good. The drawing draws none: its
   coach mark is dismissed by tapping the target. */
.gs-coach-mark__dismiss {
  grid-column: 2;
  grid-row: 1 / -1;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: var(--gs-size-touch-min);
  min-height: var(--gs-size-touch-min);
  margin: calc(var(--gs-space-2) * -1);

  font-size: var(--gs-size-icon-utility);
  line-height: 1;
  color: inherit;
  background: none;
  border: 0;
  border-radius: var(--gs-radius-full);
  cursor: pointer;
}

.gs-coach-mark__dismiss:hover { opacity: 0.8; }

.gs-coach-mark__dismiss:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* Read by a screen reader, never seen. `display: none` would drop it from the
   accessible name, which is the one thing this element is for. */
.gs-coach-mark__announcement {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  white-space: nowrap;
  clip-path: inset(50%);
  border: 0;
}
